contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address callerIsOwner, address newOwner) public payable {
        require(newOwner != address(0));

        address ownerBefore = c.owner();

        // Only the current owner may call setOwner.  The test contract is the
        // deployer, so it can force the caller identity by invoking through a
        // proxy?  No proxy allowed; instead we drive the rule with the two
        // possible msg.sender values by controlling whether we are owner.
        // We cannot change msg.sender, so we test both paths by temporarily
        // transferring ownership away (making our call unauthorized) or not.
        bool allowed = (ownerBefore == address(this));

        bool reverted;
        if (allowed) {
            // We are the owner: call must succeed and update owner.
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address ownerAfter = c.owner();
            assert(!reverted);
            assert(ownerAfter == newOwner);
        } else {
            // We are not the owner: call must revert and leave owner unchanged.
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
            address ownerAfter = c.owner();
            assert(reverted);
            assert(ownerAfter == ownerBefore);
        }
    }

    receive() external payable {}
}

