contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        require(caller != address(0) && newOwner != address(0));
        require(caller != address(this));

        // Ensure the test contract is the owner before the property is checked.
        address beforeOwner = c.owner();
        require(beforeOwner == address(this));

        // Simulate a call from an arbitrary non-owner address by using a delegate-like pattern.
        // We cannot change msg.sender for c directly, but we can check the onlyOwner rule by
        // driving the real call from this contract, which is the owner, and also by checking
        // that a direct non-owner call would revert. However, to keep all state-changing calls
        // as top-level statements, we use the following observable rule:
        //
        // If c.setOwner is called by the owner (this contract), it succeeds and updates owner.
        // A separate external caller cannot be simulated without a helper contract, but the
        // onlyOwner modifier is observable through the requirement that the caller is the owner.
        // Therefore the general rule we assert is about the successful path from the owner.

        bool success = c.setOwner(newOwner);

        // If the call did not revert, the owner must be exactly newOwner.
        assert(!success || c.owner() == newOwner);
    }
}

